/**
 * Standard Tools Extension
 *
 * Enforces a consistent, high-quality tool set across pi sessions:
 *   - `rg` instead of built-in `grep`
 *   - `fd` instead of built-in `find` / naive `ls`
 *   - `ast_grep` for structure-aware code search and rewrite
 *   - `format_file` to run Prettier or Biome automatically
 *   - `git_status` to inspect repo state before finishing
 *   - `trash` to move deleted files/folders to /tmp (no `rm`)
 *   - `quick_edit` / `target_edit` via fast-edit (standalone editing tools)
 *   - Injected system-prompt rules that tell the model to avoid
 *     `apply_patch`, built-in grep/find, destructive rm, and to use
 *     git/format/trash tools.
 *
 * Usage:
 *   pi -e /workspaces/pi-standard-tools/extension.ts
 *
 * Or copy this file (and optionally this whole folder) to
 *   ~/.pi/agent/extensions/standard-tools.ts
 * so it is loaded automatically in every session.
 */

import { execFile } from "node:child_process/promises";
import { mkdtemp, writeFile, access, readFile } from "node:fs/promises";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { Type } from "@earendil-works/pi-ai";
import {
	applyQuickEdits,
	applyTargetEdits,
	preferFastEditTools,
	numberReadText,
	QuickEditParams,
	TargetEditParams,
} from "./fast-edit.js";
import {
	isToolCallEventType,
	DEFAULT_MAX_BYTES,
	DEFAULT_MAX_LINES,
	formatSize,
	truncateHead,
	withFileMutationQueue,
	type BuildSystemPromptOptions,
	type ExtensionAPI,
	type TruncationResult,
} from "@earendil-works/pi-coding-agent";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

interface RunResult {
	stdout: string;
	stderr: string;
}

async function runCommand(
	binaries: string[],
	args: string[],
	cwd: string,
	signal?: AbortSignal,
): Promise<RunResult> {
	let lastError: Error | undefined;

	for (const binary of binaries) {
		try {
			return await execFile(binary, args, { cwd, signal });
		} catch (err: any) {
			lastError = err;
			// If the binary is missing, try the next alias.
			if (err.code === "ENOENT" || err.errno === -2) {
				continue;
			}
			// Otherwise, rethrow the error from this binary.
			throw err;
		}
	}

	throw new Error(
		`Command not found: tried ${binaries.map((b) => `"${b}"`).join(", ")}. ${lastError?.message ?? ""}`,
	);
}

async function writeTruncatedOutput(
	output: string,
	truncation: TruncationResult,
	prefix: string,
): Promise<{ text: string; fullOutputPath: string }> {
	const tempDir = await mkdtemp(join(tmpdir(), prefix));
	const fullOutputPath = join(tempDir, "output.txt");
	await withFileMutationQueue(fullOutputPath, async () => {
		await writeFile(fullOutputPath, output, "utf8");
	});

	const truncatedLines = truncation.totalLines - truncation.outputLines;
	const truncatedBytes = truncation.totalBytes - truncation.outputBytes;

	const notice = `\n\n[Output truncated: showing ${truncation.outputLines} of ${truncation.totalLines} lines (${formatSize(
		truncation.outputBytes,
	)} of ${formatSize(truncation.totalBytes)}). ${truncatedLines} lines (${formatSize(
		truncatedBytes,
	)}) omitted. Full output saved to: ${fullOutputPath}]`;

	return { text: truncation.content + notice, fullOutputPath };
}

async function maybeTruncate(
	output: string,
	prefix: string,
): Promise<{ text: string; fullOutputPath?: string }> {
	const truncation = truncateHead(output, {
		maxLines: DEFAULT_MAX_LINES,
		maxBytes: DEFAULT_MAX_BYTES,
	});

	if (!truncation.truncated) {
		return { text: truncation.content };
	}

	const { text, fullOutputPath } = await writeTruncatedOutput(output, truncation, prefix);
	return { text, fullOutputPath };
}

/**
 * Resolve a user-supplied path relative to the extension context's cwd.
 */
function resolvePath(ctx: { cwd: string }, rel: string): string {
	return resolve(ctx.cwd, rel);
}

// ---------------------------------------------------------------------------
// rg — ripgrep content search
// ---------------------------------------------------------------------------

const RgParams = Type.Object({
	pattern: Type.String({ description: "Search pattern (regex)" }),
	path: Type.Optional(Type.String({ description: "Directory or file to search (default: cwd)" })),
	glob: Type.Optional(Type.String({ description: "File glob, e.g. '*.ts'" })),
	context: Type.Optional(Type.Number({ description: "Number of context lines around each match" })),
	maxCount: Type.Optional(Type.Number({ description: "Stop after this many matches per file" })),
});

function registerRg(pi: ExtensionAPI) {
	pi.registerTool({
		name: "rg",
		label: "ripgrep",
		description:
			"Fast content search using ripgrep. Prefer this over the built-in `grep` tool. Output is truncated automatically; full output is saved to a temp file when needed.",
		parameters: RgParams,
		promptGuidelines: [
			"Use `rg` instead of the built-in `grep` tool for searching file contents.",
			"Use `glob` to narrow file scope instead of searching the whole repository.",
		],
		async execute(_toolCallId, params, signal, _onUpdate, ctx) {
			const searchPath = resolvePath(ctx, params.path || ".");
			const args = ["--line-number", "--color=never", "--heading"];

			if (params.context !== undefined && params.context > 0) {
				args.push("-C", String(params.context));
			}
			if (params.maxCount !== undefined && params.maxCount > 0) {
				args.push("-m", String(params.maxCount));
			}
			if (params.glob) {
				args.push("--glob", params.glob);
			}

			args.push(params.pattern, searchPath);

			let output: string;
			try {
				const { stdout } = await runCommand(["rg"], args, ctx.cwd, signal);
				output = stdout;
			} catch (err: any) {
				if (err.code === 1 && !err.stderr) {
					return {
						content: [{ type: "text", text: "No matches found" }],
						details: { pattern: params.pattern, path: params.path, matchCount: 0 },
					};
				}
				throw new Error(`ripgrep failed: ${err.message}`);
			}

			if (!output.trim()) {
				return {
					content: [{ type: "text", text: "No matches found" }],
					details: { pattern: params.pattern, path: params.path, matchCount: 0 },
				};
			}

			const { text, fullOutputPath } = await maybeTruncate(output, "pi-rg-");
			const matchCount = output.split("\n").filter((l) => l.trim()).length;

			return {
				content: [{ type: "text", text }],
				details: {
					pattern: params.pattern,
					path: params.path,
					matchCount,
					fullOutputPath,
				},
			};
		},
	});
}

// ---------------------------------------------------------------------------
// fd — fast file/directory discovery
// ---------------------------------------------------------------------------

const FdParams = Type.Object({
	pattern: Type.Optional(Type.String({ description: "Optional filename/regex pattern" })),
	path: Type.Optional(Type.String({ description: "Directory to search (default: cwd)" })),
	type: Type.Optional(
		Type.Union([Type.Literal("file"), Type.Literal("directory"), Type.Literal("any")], {
			description: "Search files, directories, or both",
		}),
	),
	extension: Type.Optional(Type.String({ description: "File extension, e.g. 'ts'" })),
	maxDepth: Type.Optional(Type.Number({ description: "Maximum directory depth" })),
});

function registerFd(pi: ExtensionAPI) {
	pi.registerTool({
		name: "fd",
		label: "fd",
		description:
			"Fast file/directory discovery using fd. Prefer this over the built-in `find` tool or running `ls -R`.",
		parameters: FdParams,
		promptGuidelines: [
			"Use `fd` instead of the built-in `find` tool to locate files and directories.",
			"Use `extension` or `type` to narrow results instead of post-filtering with grep.",
		],
		async execute(_toolCallId, params, signal, _onUpdate, ctx) {
			const searchPath = resolvePath(ctx, params.path || ".");
			const args = ["--color=never"];

			if (params.type && params.type !== "any") {
				args.push("--type", params.type === "directory" ? "d" : "f");
			}
			if (params.extension) {
				args.push("--extension", params.extension);
			}
			if (params.maxDepth !== undefined && params.maxDepth >= 0) {
				args.push("--max-depth", String(params.maxDepth));
			}

			args.push(params.pattern || "", searchPath);

			let output: string;
			try {
				const { stdout } = await runCommand(["fd", "fdfind"], args, ctx.cwd, signal);
				output = stdout;
			} catch (err: any) {
				if (err.code === 1 && !err.stderr) {
					return {
						content: [{ type: "text", text: "No matches found" }],
						details: { path: params.path, matchCount: 0 },
					};
				}
				throw new Error(`fd failed: ${err.message}`);
			}

			if (!output.trim()) {
				return {
					content: [{ type: "text", text: "No matches found" }],
					details: { path: params.path, matchCount: 0 },
				};
			}

			const { text, fullOutputPath } = await maybeTruncate(output, "pi-fd-");
			const matchCount = output.split("\n").filter((l) => l.trim()).length;

			return {
				content: [{ type: "text", text }],
				details: {
					path: params.path,
					matchCount,
					fullOutputPath,
				},
			};
		},
	});
}

// ---------------------------------------------------------------------------
// ast_grep — AST-based search / rewrite
// ---------------------------------------------------------------------------

const AstGrepParams = Type.Object({
	mode: Type.Optional(
		Type.Union([Type.Literal("run"), Type.Literal("scan")], {
			description: "Use 'run' for ad-hoc patterns, 'scan' for YAML rule files",
		}),
	),
	pattern: Type.Optional(Type.String({ description: "AST pattern (required for run mode)" })),
	rewrite: Type.Optional(Type.String({ description: "Replacement string (run mode only)" })),
	language: Type.Optional(Type.String({ description: "Language, e.g. ts, js, python, rust" })),
	path: Type.Optional(Type.String({ description: "Path to search (default: cwd)" })),
	rule: Type.Optional(Type.String({ description: "Path to a rule Y

/**
 * Fast Edit — standalone quick_edit / target_edit implementation for Pi.
 *
 * This is a fresh implementation (not a wrapper around pi-snap-edit) that
 * provides the same core editing primitives:
 *   - `quick_edit`: edit by 1-indexed line numbers / ranges.
 *   - `target_edit`: edit by exact literal target text markers.
 *
 * It also exposes `preferFastEditTools()` so the extension can hide the
 * built-in `edit`/`substitute_edit` tools and enable these instead.
 */

import { readFile, writeFile } from "node:fs/promises";
import { Type, type Static } from "@earendil-works/pi-ai";

// ---------------------------------------------------------------------------
// Schemas
// ---------------------------------------------------------------------------

const LineEditParams = Type.Object(
	{
		start: Type.Integer({ minimum: 1, description: "1-indexed start line number." }),
		end: Type.Optional(Type.Integer({ minimum: 1, description: "Optional 1-indexed inclusive end line number." })),
		expectedStartLine: Type.Optional(Type.String({ description: "Guard for the current start line content." })),
		expectedStartLineMatch: Type.Optional(
			Type.Union([Type.Literal("exact"), Type.Literal("trim")], {
				description: "exact (default) or trim whitespace matching.",
			}),
		),
		expectedEndLine: Type.Optional(Type.String({ description: "Guard for the current end line content." })),
		expectedLineCount: Type.Optional(
			Type.Integer({ minimum: 1, description: "Expected number of lines in the start..end range." }),
		),
		whitespace: Type.Optional(
			Type.Union([Type.Literal("strict"), Type.Literal("indent_tolerant")], {
				description: "indent_tolerant trims guards and preserves indentation.",
			}),
		),
		preserveIndent: Type.Optional(
			Type.Boolean({ description: "Prefix the start-line indentation to each non-empty replacement line." }),
		),
		lines: Type.Array(Type.String(), { description: "Replacement lines. Empty array deletes the range." }),
	},
	{ description: "Replace, insert, or delete by line number or inclusive range." },
);

const EofEditParams = Type.Object(
	{
		start: Type.Literal("eof", { description: "Append at end of file." }),
		lines: Type.Array(Type.String(), { minItems: 1, description: "Lines to append." }),
	},
	{ description: "Append-only at end of file." },
);

export const QuickEditParams = Type.Object({
	path: Type.String({ description: "Path to the file to edit." }),
	edits: Type.Array(Type.Union([EofEditParams, LineEditParams]), {
		minItems: 1,
		description: 'Line-number edits or EOF appends. Atomic: any invalid edit rejects the whole batch.',
	}),
});

export type QuickEditInput = Static<typeof QuickEditParams>;
export type Edit = QuickEditInput["edits"][number];

const TargetBase = {
	target: Type.String({ minLength: 1, description: "Exact literal target text. Use \\n for multi-line." }),
	matchMode: Type.Optional(
		Type.Union([Type.Literal("exact"), Type.Literal("trim")], {
			description: "exact (default) substring; trim compares whole lines ignoring leading/trailing whitespace.",
		}),
	),
};

export const TargetEditParams = Type.Object({
	path: Type.String({ description: "Path to the file to edit." }),
	ops: Type.Array(
		Type.Union([
			Type.Object({
				type: Type.Literal("replace"),
				...TargetBase,
				line: Type.Optional(Type.Integer({ minimum: 1 })),
				range: Type.Optional(
					Type.Object({
						startLine: Type.Integer({ minimum: 1 }),
						endLine: Type.Integer({ minimum: 1 }),
					}),
				),
				replacement: Type.String({ description: "Replacement text. Use \\n for multi-line." }),
			}),
			Type.Object({
				type: Type.Literal("delete"),
				...TargetBase,
				line: Type.Optional(Type.Integer({ minimum: 1 })),
				range: Type.Optional(
					Type.Object({
						startLine: Type.Integer({ minimum: 1 }),
						endLine: Type.Integer({ minimum: 1 }),
					}),
				),
			}),
			Type.Object({
				type: Type.Literal("insert_before"),
				...TargetBase,
				line: Type.Integer({ minimum: 1 }),
				lines: Type.Array(Type.String(), { minItems: 1 }),
			}),
			Type.Object({
				type: Type.Literal("insert_after"),
				...TargetBase,
				line: Type.Integer({ minimum: 1 }),
				lines: Type.Array(Type.String(), { minItems: 1 }),
			}),
		]),
		{ minItems: 1 },
	),
});

export type TargetEditInput = Static<typeof TargetEditParams>;
export type TargetEditOp = TargetEditInput["ops"][number];

// ---------------------------------------------------------------------------
// Error utilities
// ---------------------------------------------------------------------------

export type EditErrorCode =
	| "EXPECTED_START_LINE_MISMATCH"
	| "EXPECTED_END_LINE_MISMATCH"
	| "EXPECTED_LINE_COUNT_MISMATCH"
	| "RANGE_OUT_OF_BOUNDS"
	| "INVALID_RANGE"
	| "OVERLAPPING_RANGES"
	| "TARGET_NOT_FOUND"
	| "TARGET_AMBIGUOUS"
	| "VALIDATION"
	| "EMPTY_BATCH";

export type EditFailureCandidate = { line: number; text: string };

export type EditFailure = {
	error_code: EditErrorCode;
	message: string;
	edit_index?: number;
	op_index?: number;
	at_line?: number;
	end_line?: number;
	actual?: string;
	expected?: string;
	candidates?: EditFailureCandidate[];
	suggested?: Record<string, unknown>;
	details?: Record<string, unknown>;
};

export const FAST_EDIT_ERROR_MARKER = "--- fast-edit-error ---";

export class FastEditError extends Error {
	readonly failure: EditFailure;

	constructor(failure: EditFailure, diagnostics: Array<string | undefined> = []) {
		const body = [failure.message, ...diagnostics.filter((s): s is string => Boolean(s))].join("\n");
		super(`${body}\n${FAST_EDIT_ERROR_MARKER}\n${JSON.stringify(failure)}`);
		this.name = "FastEditError";
		this.failure = failure;
	}
}

function fail(failure: EditFailure, diagnostics: Array<string | undefined> = []): never {
	throw new FastEditError(failure, diagnostics);
}

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

function splitBom(content: string): { bom: boolean; text: string } {
	return content.startsWith("\uFEFF") ? { bom: true, text: content.slice(1) } : { bom: false, text: content };
}

function joinBom(text: string, bom: boolean): string {
	return bom ? `\uFEFF${text}` : text;
}

function splitLines(content: string): string[] {
	if (content === "") return [];
	const trimmed = content.endsWith("\n") ? content.slice(0, content.endsWith("\r\n") ? -2 : -1) : content;
	if (trimmed === "") return [];
	return trimmed.split(/\r?\n/);
}

function detectLineEnding(content: string): "\r\n" | "\n" {
	return content.includes("\r\n") ? "\r\n" : "\n";
}

function unescapeLiteral(value: string): string {
	return value.replace(/\\(n|t|r|'|"|`|\\|\n|\$)/g, (match, capturedChar: string) => {
		switch (capturedChar) {
			case "n":
				return "\n";
			case "t":
				return "\t";
			case "r":
				return "\r";
			case "'":
			case '"':
			case "`":
			case "\\":
			case "$":
			case "\n":
				return capturedChar;
			default:
				return match;
		}
	});
}

function lineMatches(actual: string, expected: string, mode: "exact" | "trim"): boolean {
	const compare = mode === "trim" ? (a: string, b: string) => a.trim() === b.trim() : (a: string, b: string) => a === b;
	if (compare(actual, expected)) return true;
	const unescaped = unescapeLiteral(expected);
	if (unescaped !== expected && compare(actual, unescaped)) return true;
	return false;
}

function matchingLineNumbers(lines: string[], expected: string, mode: "exact" | "trim"): number[] {
	const out: number[] = [];
	for (let i = 0; i < lines.length; i++) {
		if (lineMatches(lines[i]!, expected, mode)) out.push(i + 1);
	}
	return out;
}

function leadingIndent(line: string): string {
	return line.match(/^[\t ]*/)?.[0] ?? "";
}

function withPreservedIndent(lines: string[], indent: string): string[] {
	return lines.map((line) => (line === "" ? line : `${indent}${line}`));
}

// ---------------------------------------------------------------------------
// Diff / context formatting
// ---------------------------------------------------------------------------

export const CONTEXT_LINES = 5;

export type EditDiff = { oldStart: number; newStart: number; oldLines: string[]; newLines: string[] };
export type ContextRange = { startIndex: number; endIndex: number };

export function formatDiffs(diffs: EditDiff[]): string {
	if (diffs.length === 0) return "";
	const chunks = ["── diff ──"];
	for (const diff of diffs) {
		const oldEnd = diff.oldStart + Math.max(0, diff.oldLines.length - 1);
		if (diff.oldLines.length <= 1 && diff.newLines.length <= 1) {
			chunks.push(`:${diff.oldStart}`);
		} else {
			const newEnd = diff.newStart + Math.max(0, diff.newLines.length - 1);
			chunks.push(`:${diff.oldStart}-${Math.max(oldEnd, newEnd)}`);
		}
		for (const line of diff.oldLines) chunks.push(`- ${line}`);
		for (const line of diff.newLines) chunks.push(`+ ${line}`);
		chunks.push("");
	}
	return chunks.join("\n").trimEnd();
}

export function formatContexts(lines: string[], ranges: ContextRange[]): string {
	const ordered = ranges
		.filter((r) => r.startIndex < r.endIndex)
		.sort((a, b) => a.startIndex - b.startIndex);
	const merged: ContextRange[] = [];
	for (const range of ordered) {
		const previous = merged.at(-1);
		if (previous && range.startIndex <= previous.endIndex) {
			previous.endIndex = Math.max(previous.endIndex, range.endIndex);
		} else {
			merged.push({ ...range });
		}
	}
	const width = String(lines.length).length;
	return merged
		.map((range) =>
			lines
				.slice(range.startIndex, range.endIndex)
				.map((line, index) => `${String(range.startIndex + index + 1).padStart(width, " ")}| ${line}`)
				.join("\n"),
		)
		.join("\n---\n");
}

// ---------------------------------------------------------------------------
// quick_edit
// ---------------------------------------------------------------------------

type ResolvedEdit = { startLine: number; endLine: number; lines: string[]
